    """Extend horizontal repeated foreground patterns; paint extrapolated marks 1."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        counts = {v: row.count(v) for v in set(row)}
        bg = max(counts, key=counts.get)
        fg_vals = [v for v in counts if v != bg and v != 1]
        if len(fg_vals) != 1:
            continue
        fg = fg_vals[0]
        pos = [c for c, v in enumerate(row) if v == fg]
        if not pos:
            continue
        last = pos[-1]
        # A long solid foreground run is the period-one special case.
        start = last
        while start >= 0 and row[start] == fg:
            start -= 1
        run = last - start
        if run >= 5 and last < w - 1:
            for c in range(last + 1, w):
                out[r][c] = 1
            continue
        # Infer a short horizontal period from the marker positions. Require
        # repeated same-phase evidence; preserve phase and paint only predicted
        # foreground cells after the rightmost observed marker.
        best = None
        for p in range(2, min(6, w) + 1):
            residues = {c % p for c in pos}
            if len(residues) == 0:
                continue
            # A valid sparse period has repeated foreground at every active
            # phase (at least two occurrences) and comparatively few misses.
            active = [q for q in residues if sum(c % p == q for c in pos) >= 2]
            if not active:
                continue
            predicted = [c for c in range(w) if c % p in active]
            misses = sum(row[c] != fg and c <= last for c in predicted)
            if len(active) > p - 1 or misses > max(1, len(predicted) // 3):
                continue
            score = (misses, p, -len(active))
            if best is None or score < best[0]:
                best = (score, p, active)
        if best is not None and last < w - 1:
            _, p, active = best
            for c in range(last + 1, w):
                if c % p in active and row[c] == bg:
                    out[r][c] = 1
    return out
